// app/javascript/controllers/product_filter_controller.js
import { Controller } from "@hotwired/stimulus"

export default class extends Controller {
  static targets = ["input", "list", "count"]

  connect() {
    document.addEventListener("keyup", this.handleKey.bind(this))
    this.fetchProducts()
  }

  handleKey(e) { if (e.key === "Escape") this.inputTarget.value = "" }

  async fetchProducts() {
    const q = document.querySelector("#product-search").value
    const res = await fetch(`/products.json?q=${q}`)
    const products = await res.json()
    this.listTarget.innerHTML = products.map(p => `
      <div class="product">
        <h3>${p.name}</h3>
        <span>$${p.price}</span>
        <a href="/products/${p.id}">View</a>
      </div>
    `).join("")
    this.countTarget.innerHTML = products.length + " products"
  }
}

// app/controllers/products_controller.rb
def index
  @products = Product.where("name ILIKE ?", "%#{params[:q]}%")
  render json: @products
end
